export class Branding{constructor(t){this.settings=t}get name(){return String(this.settings.get("lanjutan.brandNama")||"Kalam").slice(0,28)}get accent(){const t=String(this.settings.get("lanjutan.brandWarna")||"#f6a723");return/^#[0-9a-f]{6}$/i.test(t)?t:"#f6a723"}get help(){return String(this.settings.get("lanjutan.brandBantuan")||"")}get tagline(){return"Ruang kerja penulis buku di sisi layar Anda"}apply(t){t&&(t.style.setProperty("--brand-accent",this.accent),t.dataset.brand=this.name.toLowerCase().replace(/\s+/g,"-"))}title(t=""){return t?`${this.name} — ${t}`:this.name}exportHeader(t){return{generator:`${this.name} 1.0.0`,brand:this.name,help:this.help,project:t?.title||"",exportedAt:(new Date).toISOString()}}}